"use client";

// ─── Word Ladder ─────────────────────────────────────────────────────────────
// You are given a start word and a target word. Change ONE letter at a time,
// each step has to be a real word, and you are done when you reach the target.
//
//   COLD → CORD → WORD
//
// A round is five ladders, short ones first, dealt fresh for each player (see
// deal()). Words and puzzles come from ./data (generated by tools/ladder/gen.py).
//
// How you play: tap the letter you want to change, then tap its replacement on
// the keyboard. Letters already in the right place for the target turn green.
//
// Nothing here talks to the backend yet: scores are kept on the device. A round
// is a list of words, which a server can replay and check exactly, so this game
// is a good fit for a ranked board later.

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { PUZZLES, VALID } from "./data";

const DISPLAY = '"Melon Pop", "Fredoka", ui-sans-serif, system-ui, sans-serif';
const ROUND = 5;
const PARS = [2, 3, 3, 4, 4]; // short first, so the first ladder teaches the game
const KEYS = ["qwertyuiop", "asdfghjkl", "zxcvbnm"];
const BEST_KEY = "gamearena:ladder:best";

const WORDS = new Set(VALID.split(" "));

// Every round is dealt fresh for this player. Ladders they have already seen
// are held back until the whole set has been used, so two players, or the same
// player on two rounds, do not get the same five.
const SEEN_KEY = "gamearena:ladder:seen";
function deal(): [string, string, number][] {
  let seen: string[] = [];
  try { seen = JSON.parse(localStorage.getItem(SEEN_KEY) || "[]"); } catch { /* private window */ }
  const seenSet = new Set(seen); const used = new Set<string>();
  const out = PARS.map((par) => {
    const free = (p: [string, string, number]) => p[2] === par && !used.has(p[0]) && !used.has(p[1]);
    let pool = PUZZLES.filter((p) => free(p) && !seenSet.has(p[0] + p[1]));
    if (!pool.length) pool = PUZZLES.filter(free); // seen them all: start over
    const p = pool[Math.floor(Math.random() * pool.length)]; used.add(p[0]); used.add(p[1]);
    return p;
  });
  try { localStorage.setItem(SEEN_KEY, JSON.stringify([...seen, ...out.map((p) => p[0] + p[1])].slice(-360))); } catch { /* ignore */ }
  return out;
}

// one good next word from `from` toward `to` (shortest route through accepted words)
function nextStep(from: string, to: string): string | null {
  if (from === to) return null;
  const prev = new Map<string, string>([[to, ""]]); const q = [to];
  for (let h = 0; h < q.length; h++) {
    const w = q[h];
    for (let i = 0; i < 4; i++) for (let c = 97; c < 123; c++) {
      const x = w.slice(0, i) + String.fromCharCode(c) + w.slice(i + 1);
      if (x === w || prev.has(x) || !WORDS.has(x)) continue;
      prev.set(x, w); if (x === from) return w; q.push(x);
    }
  }
  return null;
}

interface Result { start: string; target: string; par: number; steps: number; seconds: number; hints: number; skipped: boolean; points: number }
function pointsFor(par: number, steps: number, seconds: number, hints: number) {
  const route = steps <= par ? 50 : Math.max(0, 50 - (steps - par) * 10);
  const speed = Math.max(0, 50 - Math.floor(seconds / 2));
  return Math.max(20, 100 + route + speed - hints * 30);
}

export default function WordLadderPage() {
  const router = useRouter();
  const [phase, setPhase] = useState<"start" | "play" | "done">("start");
  const [set, setSet] = useState<[string, string, number][]>([]);
  const [ix, setIx] = useState(0);
  const [rungs, setRungs] = useState<string[]>([]);
  const [sel, setSel] = useState(0);
  const [msg, setMsg] = useState<{ text: string; key: number } | null>(null);
  const [shake, setShake] = useState(0);
  const [hints, setHints] = useState(0);
  const [hintWord, setHintWord] = useState<string | null>(null);
  const [solved, setSolved] = useState(false);
  const [results, setResults] = useState<Result[]>([]);
  const [secs, setSecs] = useState(0);
  const [best, setBest] = useState(0);
  const t0 = useRef(0);
  const ladderEnd = useRef<HTMLDivElement>(null);

  useEffect(() => { try { setBest(Number(localStorage.getItem(BEST_KEY) || 0)); } catch { /* private window */ } }, []);

  const puzzle = set[ix];
  const start = puzzle?.[0] ?? ""; const target = puzzle?.[1] ?? ""; const par = puzzle?.[2] ?? 0;
  const current = rungs.length ? rungs[rungs.length - 1] : start;

  const openPuzzle = useCallback((list: [string, string, number][], i: number) => {
    const [s, t] = list[i];
    setIx(i); setRungs([]); setHints(0); setHintWord(null); setSolved(false); setMsg(null);
    setSel(Math.max(0, [0, 1, 2, 3].findIndex((k) => s[k] !== t[k])));
    t0.current = Date.now(); setSecs(0);
  }, []);
  const begin = () => {
    const list = deal();
    setSet(list); setResults([]); setPhase("play"); openPuzzle(list, 0);
  };

  useEffect(() => {
    if (phase !== "play" || solved) return;
    const t = setInterval(() => setSecs(Math.floor((Date.now() - t0.current) / 1000)), 500);
    return () => clearInterval(t);
  }, [phase, solved, ix]);
  useEffect(() => { ladderEnd.current?.scrollIntoView({ block: "nearest", behavior: "smooth" }); }, [rungs.length]);

  const say = (text: string) => setMsg({ text, key: Date.now() });
  const finishPuzzle = (steps: number, skipped: boolean) => {
    const seconds = Math.floor((Date.now() - t0.current) / 1000);
    const r: Result = { start, target, par, steps, seconds, hints, skipped, points: skipped ? 0 : pointsFor(par, steps, seconds, hints) };
    const all = [...results, r]; setResults(all); setSolved(true);
    setTimeout(() => {
      if (ix + 1 < ROUND) openPuzzle(set, ix + 1);
      else {
        const total = all.reduce((a, x) => a + x.points, 0);
        if (total > best) { setBest(total); try { localStorage.setItem(BEST_KEY, String(total)); } catch { /* ignore */ } }
        setPhase("done");
      }
    }, skipped ? 500 : 1300);
  };

  const type = useCallback((letter: string) => {
    if (phase !== "play" || solved || !puzzle) return;
    if (current[sel] === letter) return;
    const next = current.slice(0, sel) + letter + current.slice(sel + 1);
    if (!WORDS.has(next)) { setShake((n) => n + 1); say(`${next.toUpperCase()} is not a word`); try { navigator.vibrate?.(40); } catch { /* no haptics */ } return; }
    if (next === start || rungs.includes(next)) { setShake((n) => n + 1); say("You already used that word"); return; }
    const list = [...rungs, next]; setRungs(list); setHintWord(null); setMsg(null);
    if (next === target) { finishPuzzle(list.length, false); return; }
    const nxt = [0, 1, 2, 3].findIndex((k) => next[k] !== target[k]);
    if (next[sel] === target[sel] && nxt >= 0) setSel(nxt);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase, solved, puzzle, current, sel, rungs, start, target]);
  const undo = () => { if (!solved && rungs.length) { setRungs(rungs.slice(0, -1)); setHintWord(null); setMsg(null); } };
  const hint = () => {
    if (solved) return;
    const w = nextStep(current, target);
    if (!w) { say("No route from here. Undo a step"); return; }
    setHints((h) => h + 1); setHintWord(w); setSel([0, 1, 2, 3].findIndex((k) => w[k] !== current[k]));
  };

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (phase !== "play") return;
      if (e.key === "ArrowLeft") setSel((s) => (s + 3) % 4);
      else if (e.key === "ArrowRight") setSel((s) => (s + 1) % 4);
      else if (e.key === "Backspace") undo();
      else if (/^[a-zA-Z]$/.test(e.key) && !e.metaKey && !e.ctrlKey && !e.altKey) type(e.key.toLowerCase());
    };
    window.addEventListener("keydown", onKey); return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase, type, rungs, solved]);

  const total = useMemo(() => results.reduce((a, x) => a + x.points, 0), [results]);
  const share = async () => {
    const lines = results.map((r) => (r.skipped ? "⬜" : r.steps <= r.par ? "🟩" : "🟨")).join("");
    const text = `Word Ladder on GameArena\n${lines}  ${total} pts\nhttps://gamearenahq.xyz/games/ladder`;
    try { if (navigator.share) await navigator.share({ text }); else { await navigator.clipboard.writeText(text); say("Copied"); } } catch { /* cancelled */ }
  };

  // `from` is the word above this one: the letter that differs from it is the
  // move the player made, and gets a ring so the route reads at a glance.
  const Tiles = ({ word, kind, from, onTap }: { word: string; kind: "start" | "target" | "rung" | "live" | "ghost"; from?: string; onTap?: (i: number) => void }) => (
    <div className={`wl-row ${kind}`}>
      {word.split("").map((ch, i) => (
        <button key={i} disabled={!onTap} onClick={() => onTap?.(i)} style={{ animationDelay: `${i * 70}ms` }}
          className={`wl-tile${kind !== "target" && kind !== "ghost" && ch === target[i] ? " hit" : ""}${from && from[i] !== ch ? " moved" : ""}${kind === "live" && i === sel && !solved ? " sel" : ""}${hintWord && kind === "live" && hintWord[i] !== ch ? " nudge" : ""}`}
          aria-label={kind === "live" ? `Letter ${i + 1}: ${ch}${i === sel ? ", selected" : ""}` : undefined}>
          {kind === "ghost" ? "" : ch}
        </button>
      ))}
    </div>
  );
  const ghosts = solved ? 0 : Math.max(0, Math.min(3, par - rungs.length - 1));
  const matched = [0, 1, 2, 3].filter((k) => current[k] === target[k]).length;

  return (
    <div className="wl">
      <header className="wl-top">
        <button className="wl-back" onClick={() => (phase === "play" ? setPhase("start") : router.push("/dashboard"))} aria-label="Back">←</button>
        <b style={{ fontFamily: DISPLAY }}>Word Ladder</b>
        {phase === "play" ? <span className="wl-meta">{total}</span> : <span className="wl-meta" />}
      </header>
      {phase === "play" && (
        <div className="wl-pips" aria-label={`Ladder ${ix + 1} of ${ROUND}`}>
          {Array.from({ length: ROUND }, (_, i) => {
            const r = results[i];
            return <i key={i} className={r ? (r.skipped ? "skip" : r.steps <= r.par ? "gold" : "ok") : i === ix ? "now" : ""} />;
          })}
        </div>
      )}

      {phase === "start" && (
        <main className="wl-start">
          <div className="wl-hero">
            <div className="wl-demo" aria-hidden>
              {["cold", "cord", "word"].map((w, r) => (
                <div key={w} className="wl-row demo" style={{ animationDelay: `${r * 0.55}s` }}>
                  {w.split("").map((ch, i) => <span key={i} className={`wl-tile${ch === "word"[i] ? " hit" : ""}${r > 0 && ["cold", "cord", "word"][r - 1][i] !== ch ? " moved" : ""}`}>{ch}</span>)}
                </div>
              ))}
            </div>
          </div>
          <h1 style={{ fontFamily: DISPLAY }}>Turn one word<br />into another</h1>
          <p>Change <b>one letter</b> at a time. Every step has to be a real word.</p>
          <button className="wl-primary" style={{ fontFamily: DISPLAY }} onClick={begin}>Play</button>
          <div className="wl-facts">
            <span><b>5</b>ladders a round</span>
            <span><b>200</b>points each</span>
            <span><b>{best || "–"}</b>your best</span>
          </div>
        </main>
      )}

      {phase === "play" && puzzle && (
        <main className="wl-play">
          <div className="wl-stats">
            <span><b>{rungs.length}</b>steps</span>
            <span><b>{par}</b>par</span>
            <span><b>{secs}s</b>time</span>
          </div>

          {/* the ladder: start at the top, the target waiting at the bottom, your
              words filling the gap. Empty rungs show roughly how far is left. */}
          <div className="wl-ladder">
            <div className="wl-rails" key={ix}>
              <Tiles word={start} kind={rungs.length ? "start" : "live"} onTap={rungs.length || solved ? undefined : setSel} />
              {rungs.map((w, i) => {
                const live = i === rungs.length - 1;
                if (live && w === target) return null; // the target row below shows it
                return <div key={`${w}${i}`} className={live && !solved ? `wl-shake-${shake % 2}` : ""}><Tiles word={w} from={i ? rungs[i - 1] : start} kind={live ? "live" : "rung"} onTap={live && !solved ? setSel : undefined} /></div>;
              })}
              {rungs.length === 0 && shake > 0 ? <span className={`wl-shake-${shake % 2}`} /> : null}
              {Array.from({ length: ghosts }, (_, g) => <Tiles key={`g${g}`} word="    " kind="ghost" />)}
              <div className={`wl-target${solved && !results[results.length - 1]?.skipped ? " won" : ""}`}>
                <span>{solved ? (results[results.length - 1]?.skipped ? "SKIPPED" : rungs.length <= par ? "PERFECT ROUTE" : "SOLVED") : `TARGET · ${matched} of 4 letters in place`}</span>
                <Tiles word={target} kind={solved && !results[results.length - 1]?.skipped ? "rung" : "target"} from={solved && rungs.length > 1 ? rungs[rungs.length - 2] : solved ? start : undefined} />
                {solved && !results[results.length - 1]?.skipped && <em style={{ fontFamily: DISPLAY }}>+{results[results.length - 1]?.points}</em>}
              </div>
              <div ref={ladderEnd} />
            </div>
          </div>

          <div className="wl-msg" key={msg?.key ?? "none"} role="status">{hintWord ? `Try ${hintWord.toUpperCase()}` : msg?.text ?? (rungs.length === 0 ? "Tap a letter, then tap what to change it to" : "")}</div>

          <div className="wl-keys">
            {KEYS.map((row, r) => (
              <div key={row}>
                {r === 2 && <button className="wide" onClick={undo} disabled={!rungs.length || solved} aria-label="Undo">↶</button>}
                {row.split("").map((k) => <button key={k} onClick={() => type(k)} className={hintWord && hintWord[sel] === k ? "glow" : ""}>{k}</button>)}
                {r === 2 && <button className="wide" onClick={hint} disabled={solved} aria-label="Hint, costs 30 points">?</button>}
              </div>
            ))}
          </div>
          <button className="wl-skip" onClick={() => !solved && finishPuzzle(rungs.length, true)} disabled={solved}>Skip this ladder</button>
        </main>
      )}

      {phase === "done" && (
        <main className="wl-done">
          <div className="wl-kicker">ROUND COMPLETE</div>
          <h1 style={{ fontFamily: DISPLAY }}>{total} <small>points</small></h1>
          {total >= best && total > 0 && <div className="wl-new">New best</div>}
          <ul>
            {results.map((r, i) => (
              <li key={i}>
                <b>{r.start.toUpperCase()} → {r.target.toUpperCase()}</b>
                <span>{r.skipped ? "skipped" : `${r.steps} step${r.steps === 1 ? "" : "s"} (par ${r.par}) · ${r.seconds}s`}</span>
                <i className={r.skipped ? "" : r.steps <= r.par ? "g" : "y"}>{r.points}</i>
              </li>
            ))}
          </ul>
          <button className="wl-primary" style={{ fontFamily: DISPLAY }} onClick={begin}>Play again</button>
          <div className="wl-pair"><button className="wl-ghost" onClick={share}>Share</button><button className="wl-ghost" onClick={() => router.push("/dashboard")}>Home</button></div>
          {msg && <div className="wl-msg" key={msg.key}>{msg.text}</div>}
        </main>
      )}

      <style>{`
        .wl { min-height: 100dvh; display: flex; flex-direction: column; background: radial-gradient(120% 60% at 50% 0%, #fbf8ff 0%, #f0e8ff 45%, #e2d6ff 100%); color: #22104f; font-family: ui-sans-serif, system-ui, -apple-system, sans-serif; --brand: #6d28d9; --line: rgba(76,29,149,0.16); --dim: rgba(34,16,79,0.6); --go: #16a34a; }
        .wl button { font: inherit; color: inherit; cursor: pointer; -webkit-tap-highlight-color: transparent; }
        .wl-top { display: grid; grid-template-columns: 56px 1fr 56px; align-items: center; padding: 10px 14px 4px; text-align: center; }
        .wl-top b { font-size: 20px; font-weight: 400; }
        .wl-back { width: 40px; height: 40px; border-radius: 14px; border: 1px solid var(--line); background: #fff; font-size: 18px; }
        .wl-meta { justify-self: end; min-width: 40px; font-family: 'Melon Pop', 'Fredoka', sans-serif; font-size: 20px; color: var(--brand); font-variant-numeric: tabular-nums; }
        .wl-pips { display: flex; justify-content: center; gap: 6px; padding: 2px 0 6px; }
        .wl-pips i { width: 34px; height: 6px; border-radius: 99px; background: rgba(76,29,149,0.14); transition: background .3s ease, transform .3s ease; }
        .wl-pips i.now { background: var(--brand); transform: scaleY(1.4); }
        .wl-pips i.gold { background: var(--go); } .wl-pips i.ok { background: #f59e0b; } .wl-pips i.skip { background: rgba(76,29,149,0.34); }
        .wl main { flex: 1; width: 100%; max-width: 460px; margin: 0 auto; padding: 4px 16px 14px; display: flex; flex-direction: column; min-height: 0; }

        .wl-row { position: relative; z-index: 1; display: flex; justify-content: center; gap: 8px; }
        .wl-tile { position: relative; width: 56px; height: 56px; display: grid; place-items: center; border-radius: 16px; border: none; background: #fff; box-shadow: 0 4px 0 rgba(76,29,149,0.2), 0 0 0 1.5px rgba(76,29,149,0.1) inset; font-size: 27px; font-weight: 800; text-transform: uppercase; color: #22104f; padding: 0; transition: transform .16s cubic-bezier(.2,.9,.3,1.4), background .25s ease, color .25s ease, box-shadow .2s ease; }
        .wl-tile:disabled { cursor: default; }
        .wl-tile.hit { background: linear-gradient(180deg, #22c55e, #16a34a); color: #fff; box-shadow: 0 4px 0 #166534; }
        .wl-tile.moved::after { content: ""; position: absolute; left: 22%; right: 22%; bottom: 7px; height: 3px; border-radius: 3px; background: var(--brand); }
        .wl-tile.hit.moved::after { background: #fff; opacity: 0.9; }
        .wl-row.start .wl-tile, .wl-row.rung .wl-tile { width: 46px; height: 46px; font-size: 21px; border-radius: 13px; box-shadow: 0 3px 0 rgba(76,29,149,0.16), 0 0 0 1.5px rgba(76,29,149,0.08) inset; }
        .wl-row.start .wl-tile.hit, .wl-row.rung .wl-tile.hit { box-shadow: 0 3px 0 #166534; }
        .wl-row.rung .wl-tile.moved::after, .wl-row.start .wl-tile.moved::after { bottom: 5px; }
        .wl-row.ghost .wl-tile { width: 46px; height: 46px; background: rgba(255,255,255,0.35); box-shadow: 0 0 0 1.5px rgba(76,29,149,0.14) inset; border-radius: 13px; }
        .wl-row.target .wl-tile { width: 50px; height: 50px; font-size: 23px; background: rgba(109,40,217,0.08); box-shadow: 0 0 0 2px rgba(109,40,217,0.4) inset; color: var(--brand); border-radius: 14px; }
        .wl-row.live .wl-tile { animation: wlFlip .42s cubic-bezier(.2,.8,.2,1) both; }
        @keyframes wlFlip { from { transform: rotateX(90deg); opacity: 0; } to { transform: none; opacity: 1; } }
        .wl-row.live .wl-tile.sel { transform: translateY(-6px); box-shadow: 0 10px 0 rgba(109,40,217,0.34), 0 0 0 3px var(--brand) inset; }
        .wl-row.live .wl-tile.sel.hit { box-shadow: 0 10px 0 #166534, 0 0 0 3px #fff inset; }
        .wl-row.live .wl-tile.nudge { animation: wlNudge .7s ease-in-out infinite; }
        @keyframes wlNudge { 50% { transform: translateY(-9px); } }

        .wl-start { text-align: center; justify-content: center; gap: 14px; }
        .wl-hero { align-self: center; padding: 20px 22px; border-radius: 30px; background: #fff; box-shadow: 0 30px 50px -30px rgba(76,29,149,0.7), 0 0 0 1px var(--line); transform: rotate(-2deg); margin-bottom: 8px; }
        .wl-demo { display: flex; flex-direction: column; gap: 8px; }
        .wl-row.demo { animation: wlDrop .5s cubic-bezier(.2,.8,.2,1) both; }
        .wl-row.demo .wl-tile { width: 50px; height: 50px; font-size: 23px; }
        @keyframes wlDrop { from { opacity: 0; transform: translateY(-16px) scale(0.9); } to { opacity: 1; transform: none; } }
        .wl-start h1 { margin: 0; font-size: clamp(32px, 9vw, 44px); line-height: 1.04; font-weight: 400; }
        .wl-start p { margin: 0 0 4px; font-size: 16px; line-height: 1.45; color: var(--dim); }
        .wl-start p b { color: #22104f; }
        .wl-primary { width: 100%; padding: 17px 0; border: none; border-radius: 20px; font-size: 22px; color: #fff !important; background: linear-gradient(180deg, #7c3aed, #6d28d9); box-shadow: 0 6px 0 #4c1d95, 0 22px 34px -16px rgba(109,40,217,0.95); transition: transform .12s ease, box-shadow .12s ease; }
        .wl-primary:active { transform: translateY(4px); box-shadow: 0 2px 0 #4c1d95; }
        .wl-ghost { width: 100%; padding: 13px 0; border-radius: 16px; border: 1px solid var(--line); background: #fff; font-size: 15px; font-weight: 800; }
        .wl-facts, .wl-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
        .wl-facts span, .wl-stats span { display: flex; flex-direction: column; align-items: center; gap: 1px; padding: 9px 4px; border-radius: 16px; background: rgba(255,255,255,0.7); border: 1px solid var(--line); font-size: 11px; font-weight: 700; letter-spacing: 0.04em; color: var(--dim); }
        .wl-facts b, .wl-stats b { font-size: 19px; color: #22104f; font-variant-numeric: tabular-nums; letter-spacing: 0; }

        .wl-play { gap: 8px; }
        .wl-stats span { padding: 6px 4px; border-radius: 14px; } .wl-stats b { font-size: 17px; }
        .wl-ladder { flex: 1; min-height: 150px; overflow-y: auto; display: flex; flex-direction: column; scrollbar-width: none; }
        .wl-ladder::-webkit-scrollbar { display: none; }
        /* the two side rails that make it a ladder */
        .wl-rails { position: relative; margin: auto; display: flex; flex-direction: column; align-items: center; gap: 9px; padding: 10px 26px; animation: wlIn .35s ease both; }
        .wl-rails::before, .wl-rails::after { content: ""; position: absolute; top: 0; bottom: 0; width: 6px; border-radius: 6px; background: linear-gradient(180deg, rgba(109,40,217,0.12), rgba(109,40,217,0.3)); }
        .wl-rails::before { left: 8px; } .wl-rails::after { right: 8px; }
        @keyframes wlIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
        .wl-target { position: relative; display: flex; flex-direction: column; align-items: center; gap: 5px; margin-top: 4px; padding-top: 8px; border-top: 2px dashed rgba(109,40,217,0.28); }
        .wl-target > span { font-size: 10px; font-weight: 900; letter-spacing: 0.14em; color: var(--brand); }
        .wl-target.won > span { color: var(--go); }
        .wl-target.won .wl-tile { width: 54px; height: 54px; font-size: 25px; animation: wlWin .6s cubic-bezier(.2,.9,.3,1.5) both; }
        @keyframes wlWin { 0% { transform: scale(0.6) rotate(-8deg); } 60% { transform: scale(1.14) rotate(3deg); } 100% { transform: none; } }
        .wl-target em { position: absolute; right: 4px; top: -22px; font-style: normal; font-size: 22px; color: var(--brand); animation: wlFloat 1.1s ease-out both; }
        @keyframes wlFloat { from { opacity: 0; transform: translateY(14px) scale(0.7); } 30% { opacity: 1; } to { opacity: 1; transform: translateY(-6px) scale(1); } }
        .wl-shake-0 { animation: wlShakeA .3s; } .wl-shake-1 { animation: wlShakeB .3s; }
        @keyframes wlShakeA { 25% { transform: translateX(-8px); } 75% { transform: translateX(8px); } }
        @keyframes wlShakeB { 25% { transform: translateX(8px); } 75% { transform: translateX(-8px); } }
        .wl-msg { min-height: 20px; text-align: center; font-size: 13.5px; font-weight: 700; color: var(--dim); animation: wlFade .25s ease both; }
        @keyframes wlFade { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }

        .wl-keys { display: flex; flex-direction: column; gap: 6px; }
        .wl-keys > div { display: flex; justify-content: center; gap: 5px; }
        .wl-keys button { flex: 1 1 0; max-width: 40px; height: 50px; border-radius: 11px; border: none; background: #fff; box-shadow: 0 3px 0 rgba(76,29,149,0.22); font-size: 17px; font-weight: 800; text-transform: uppercase; padding: 0; transition: transform .08s ease, background .15s ease; }
        .wl-keys button:active { transform: translateY(3px); box-shadow: none; background: #e9defe; }
        .wl-keys button.wide { max-width: 54px; flex-grow: 1.5; background: #ede4ff; color: var(--brand); font-size: 20px; }
        .wl-keys button:disabled { opacity: 0.4; cursor: default; }
        .wl-keys button.glow { background: var(--brand); color: #fff; animation: wlNudge .7s ease-in-out infinite; }
        .wl-skip { align-self: center; margin-top: 2px; padding: 6px 12px calc(env(safe-area-inset-bottom, 0px) + 6px); border: none; background: none; font-size: 12.5px; font-weight: 700; color: var(--dim); text-decoration: underline; text-underline-offset: 3px; }
        .wl-skip:disabled { opacity: 0.3; }

        .wl-done { text-align: center; justify-content: center; gap: 12px; }
        .wl-kicker { font-size: 11px; font-weight: 900; letter-spacing: 0.2em; color: var(--brand); }
        .wl-done h1 { margin: 0; font-size: 72px; line-height: 1; font-weight: 400; animation: wlWin .6s cubic-bezier(.2,.9,.3,1.5) both; }
        .wl-done h1 small { font-size: 18px; color: var(--dim); }
        .wl-new { align-self: center; padding: 5px 14px; border-radius: 999px; background: var(--go); color: #fff; font-size: 12px; font-weight: 900; letter-spacing: 0.08em; }
        .wl-done ul { list-style: none; margin: 4px 0 6px; padding: 0; display: flex; flex-direction: column; gap: 6px; text-align: left; }
        .wl-done li { display: grid; grid-template-columns: 1fr auto; column-gap: 10px; padding: 10px 14px; border-radius: 16px; background: #fff; box-shadow: 0 0 0 1px var(--line); animation: wlIn .4s ease both; }
        .wl-done li:nth-child(2) { animation-delay: .06s; } .wl-done li:nth-child(3) { animation-delay: .12s; } .wl-done li:nth-child(4) { animation-delay: .18s; } .wl-done li:nth-child(5) { animation-delay: .24s; }
        .wl-done li b { font-size: 14.5px; letter-spacing: 0.04em; }
        .wl-done li span { grid-column: 1; font-size: 12px; color: var(--dim); font-weight: 600; }
        .wl-done li i { grid-row: 1 / span 2; grid-column: 2; align-self: center; font-style: normal; font-size: 18px; font-weight: 900; color: var(--dim); }
        .wl-done li i.g { color: #15803d; } .wl-done li i.y { color: #b45309; }
        .wl-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }

        @media (max-height: 700px) { .wl-tile { width: 48px; height: 48px; font-size: 23px; } .wl-row.start .wl-tile, .wl-row.rung .wl-tile, .wl-row.ghost .wl-tile { width: 36px; height: 36px; font-size: 16px; border-radius: 10px; } .wl-row.target .wl-tile { width: 40px; height: 40px; font-size: 18px; } .wl-keys button { height: 42px; } .wl-rails { gap: 6px; padding: 6px 24px; } .wl-stats span { padding: 4px; } .wl-hero { padding: 14px 16px; } }
        @media (min-width: 900px) { .wl main { max-width: 520px; } .wl-keys button { max-width: 46px; } }
        @media (prefers-reduced-motion: reduce) { .wl * { animation: none !important; transition: none !important; } }
      `}</style>
    </div>
  );
}
